UPDATE banks SET questions_json = '[{"id":1,"type":"essay","category":"控制线路设计与制动原理","difficulty":2,"question":"在电气控制线路设计中，电器线圈回路为什么不能串联自身的常闭触点？","options":[],"answer":"电器线圈回路不能串联自身的常闭触点。","explanation":"核心设计禁忌。如果线圈回路串联了自身的常闭触点，线圈通电动作的瞬间就会把自己的常闭触点断开，导致自己立即断电，电路会陷入不停震荡敲击的状态，无法正常工作。"},{"id":2,"type":"essay","category":"控制线路设计与制动原理","difficulty":2,"question":"在交流控制电路中，为什么不能串联两个电器的线圈？","options":[],"answer":"在交流控制电路中不能串联两个电器的线圈。","explanation":"核心设计禁忌。两个交流线圈串联时，由于阻抗分压，每个线圈上的电压都达不到额定值，会导致两个接触器都无法正常吸合，甚至烧毁线圈。"},{"id":3,"type":"essay","category":"控制线路设计与制动原理","difficulty":2,"question":"请写出多地点控制线路的组成原则。","options":[],"answer":"各地点的启动按钮应并联连接，各地点的停止按钮应串联连接。","explanation":"核心组成原则。记忆口诀：“并起串停”。这样才能做到在任何一个地方按下启动都能开机，按下停止都能关机。"},{"id":4,"type":"essay","category":"控制线路设计与制动原理","difficulty":3,"question":"什么是能耗制动控制？请简述其具体工作原理。","options":[],"answer":"所谓能耗制动，是指在电动机脱离三相交流电源后，立即在定子绕组的任意两相通入低压直流电流，使其在电动机内部产生恒定磁场。由于惯性，电动机在这个磁场中仍按原方向继续旋转，转子内产生感应电势和感应电流。该电流与恒定磁场相互作用，产生与转子旋转方向相反的制动转矩，从而使电动机转速迅速下降，达到制动目的。当转速降为零时，转子对磁场无相对运动，转子中的感应电势和感应电流变为零，制动转矩消失，电动机停转，制动过程结束。","explanation":"","img":""},{"id":5,"type":"essay","category":"控制线路设计与制动原理","difficulty":3,"question":"简述时间原则的 Y-Δ 降压启动控制线路的完整启动过程及各接触器的动作顺序。","options":[],"answer":"当启动电动机时，合上开关 QX，按下启动按钮 SB1，主接触器 KM1、Y形接法接触器 KM2 与时间继电器 KT 的线圈同时得电，接触器 KM2 的主触点闭合，将电动机接成 Y 形并经 KM1 的主触点接至三相电源上，电动机降压启动。当到达 KT 的延时设定值时，KT 的延时常闭触点打开，KM2 线圈失电；同时 KT 延时闭合常开触点闭合，Δ形接法接触器 KM3 线圈得电，将电动机换接成 Δ 形。至此，电动机启动过程结束而转入正常运行。同时，KM3 的常闭辅助触点打开，KT 线圈断电，以节省电能和延长电器元件的使用寿命。另外，KT 触点瞬时恢复正常状态，为下一次启动做好准备。","explanation":"","img":"https://cdn.jsdu.cn/opdav/20260607/221639787eb71485d0a92737b7d3dee2.png"},{"id":6,"type":"essay","category":"PLC工作原理与指令","difficulty":2,"question":"在 S7-200 系列 PLC 的定时器指令中，计数预设值（PV）最大值是多少？有什么时间长度限制？","options":[],"answer":"PV 为计数预设值，最大值为 3276.7（小于一个小时）。","explanation":"对应核心重点第1条。预设值最大代表的时间长度小于一小时。"},{"id":7,"type":"essay","category":"PLC工作原理与指令","difficulty":2,"question":"S7-200 系列 PLC 提供了哪三种接通或断开延时定时器指令？","options":[],"answer":"1. 接通延时定时器指令（TON）\\n2. 有记忆的接通延时定时器指令（TONR）\\n3. 断开延时定时器指令（TOF）","explanation":"对应核心重点第2、3、4条。这是PLC最基础的三种定时器指令类型。"},{"id":8,"type":"essay","category":"PLC工作原理与指令","difficulty":2,"question":"PLC 共有多少个定时器？它们分为哪几种分辨率？","options":[],"answer":"PLC 共有 256 个定时器，分为三种分辨率：1ms、10ms、100ms。","explanation":"对应核心重点第5条。定时器号决定了定时器的类型及其对应的分辨率。"},{"id":9,"type":"essay","category":"PLC工作原理与指令","difficulty":1,"question":"简述 PLC 梯形图的结构组成及结束标志。","options":[],"answer":"梯形图由多个梯级（或网络组成），最后以线圈或盒结束。","explanation":"对应核心重点第6条。这是梯形图编写的基本结构规范。"},{"id":10,"type":"essay","category":"PLC工作原理与寻址","difficulty":2,"question":"PLC 执行用户程序采用了什么工作方式？包含哪三个主要阶段？","options":[],"answer":"PLC 执行程序是按周期性循环扫描的方式进行的。每一次扫描所用的时间称为一个扫描周期。每个扫描过程主要分为三个阶段，即输入采样阶段、程序执行阶段和输出刷新阶段。","explanation":"课本原文章节画线重点。核心要点是周期性循环扫描和输入采样、程序执行、输出刷新三阶段。"},{"id":11,"type":"essay","category":"PLC工作原理与寻址","difficulty":2,"question":"PLC 提供了哪三种操作数寻址方式？","options":[],"answer":"立即寻址、直接寻址和间接寻址。","explanation":"","img":""},{"id":12,"type":"essay","category":"PLC工作原理与寻址","difficulty":2,"question":"在 PLC 存储器单元的数据存取中，按字节寻址、字寻址、双字寻址时，对应的长度字符分别是什么？分别代表多少位？","options":[],"answer":"1. 字节寻址：长度符为“B”，代表 8 位数据。\\n2. 字寻址：长度符为“W”，代表 16 位数据。\\n3. 双字寻址：长度符为“D”，代表 32 位数据。","explanation":"依据课本寻址手写标注及“数据均可按位、字节、字和双字来存取”的原文整理。"},{"id":13,"type":"essay","category":"步进电动机控制","difficulty":2,"question":"简述步进电动机的主要运行特点有哪些？","options":[],"answer":"1. 易于实现数字控制：步进电动机严格受数字脉冲信号的控制，输出角位移与输入脉冲数成正比（θ=Nβ），转速与输入脉冲频率成正比（n=βf/6）。\\n2. 转向调节方便：可以通过改变绕组通电相序来改变转动方向。\\n3. 具有自锁能力：当停止输入脉冲时，只要某些相的控制绕组仍保持通电状态，电动机就可以保持在该固定位置上，实现停车时转子定位。\\n4. 步距角误差不会长期累积：由于步进电动机每转一周都有固定的步数，当转子转过 360° 后又恢复原来位置，累积误差将变为零，只有周期性误差，而无累积误差。\\n5. 多用于构成开环控制系统：由于无需位置和速度检测反馈装置，结构简单，使用维护方便，位置精度较高，广泛应用于构成开环位置伺服系统。","explanation":"课本“步进电动机的特点”完整章节划线要点总结。"},{"id":14,"type":"essay","category":"步进电动机控制","difficulty":2,"question":"什么是步进电动机的步距角？它的精度和什么因素有关？可以通过什么方式改变它？","options":[],"answer":"1. 定义：步距角是指在一个电脉冲的作用下，步进电动机转子所转过的角度。\\n2. 精度关系：步距角越小，步进电动机的位置精度越高。\\n3. 改变方式：步进电动机一旦选定后，其步距角就固定不变，可以通过改变通电方式来获得两种步距角。","explanation":"依据课本关于“步距角”核心性能指标的画线内容提取。"},{"id":15,"type":"essay","category":"步进电动机控制","difficulty":3,"question":"写出三相步进电动机在“三相三拍”、“三相双三拍”和“单双六拍”通电方式下的正转通电相序。","options":[],"answer":"1. 三相三拍：A → B → C → A\\n2. 三相双三拍：AB → BC → CA → AB\\n3. 单双六拍（三相六拍）：A → AB → B → BC → C → CA → A","explanation":"来自课本手写补充标注的核心励磁通电相序。","img":"https://cdn.jsdu.cn/opdav/20260607/4cabe74e86a9c2b859c25d966a1dd156.png"},{"id":16,"type":"essay","category":"步进电动机控制","difficulty":3,"question":"在三相六拍环形脉冲分配表中，正转通电相 A、AB、B、BC、C、CA 对应的十六进制控制代码（转向代码）分别是什么？","options":[],"answer":"1. A 相通电对应代码：01H\\n2. AB 相通电对应代码：03H\\n3. B 相通电对应代码：02H\\n4. BC 相通电对应代码：06H\\n5. C 相通电对应代码：04H\\n6. CA 相通电对应代码：05H","explanation":"严格提取自课本分配表中画线的核心十六进制代码。","img":"https://cdn.jsdu.cn/opdav/20260607/4cabe74e86a9c2b859c25d966a1dd156.png"},{"id":17,"type":"essay","category":"直流伺服电动机","difficulty":3,"question":"直流伺服电动机有哪三种调速方法？请写出调速方程表达式，并注明方程中各项代表的含义。","options":[],"answer":"调速方法：\\n1. 改变 Ra（电枢回路电阻）\\n2. 改变 U（电枢电压）\\n3. 改变 磁通 Φ（弱磁调速）\\n\\n调速方程：\\nn = U / (Ke·Φ) - Ra / (Ke·Kt·Φ^2) · T\\n\\n式中：\\nn —— 电动机转速；\\nT —— 电动机转矩；\\nU —— 电枢电压；\\nRa —— 电枢回路电阻；\\nΦ —— 每极磁通；\\nKe、Kt —— 电动机结构常数。","explanation":"对应直流电机控制页手写标注的核心调速方程及调速方法分类。"},{"id":18,"type":"essay","category":"直流伺服电动机","difficulty":2,"question":"写出电动机机械特性硬度 β 的计算公式，并说明依据其大小机械特性如何进行分类和代表电机。","options":[],"answer":"计算公式：\\nβ = dT / dn = ΔT / Δn × 100%\\n\\n特性分类：\\n1. β → ∞ ：绝对硬特性（代表电机：同步电机）。\\n2. β > 10 ：硬特性。\\n3. β < 10 ：软特性（代表情况：他励电动机串大电阻，手写原字为徐励）。","explanation":"完全对应直流电机页右下方手写公式和分类标准笔记。"},{"id":19,"type":"essay","category":"低压电器基础","difficulty":2,"question":"为什么热继电器（FR）不能用作电动机的短路保护？在为 Δ 接法的三相异步电动机选择热继电器时有什么特殊要求？","options":[],"answer":"1. 原因：因为热继电器具有很大的热惯性，在电路发生短路时无法立即动作以使电路瞬时断开，所以不能用作短路保护。\\n2. 选择要求：如果电动机是 Δ 接法，则必须采用带断相保护的三相热继电器。","explanation":"严格依据教材热继电器画线原文。大热惯性使其无法实现瞬时短路分断；三角形接法必须选配带断相保护的三相热继电器。"},{"id":20,"type":"essay","category":"低压电器基础","difficulty":2,"question":"简述交流接触器与直流接触器在铁芯结构、发热特性及适用场合上的主要区别。","options":[],"answer":"1. 交流接触器：当交变磁通穿过铁芯时将产生涡流和磁滞损耗，使铁芯发热。为了减少因涡流和磁滞损耗造成的能量损失，铁芯用硅钢片冲制后叠铆而成。交流接触器线圈匝数较少，电阻小，吸合瞬间电流可达到工作电流的10~15倍，若频繁动作易烧毁线圈，不宜用于频繁启停的系统。\\n2. 直流接触器：铁芯中流过的是直流电，不会产生涡流和磁滞损耗，故不会发热。为了便于加工，铁芯用整块电工软钢制成。通常将线圈绕制成长而薄的圆筒状。直流接触器的线圈中为直流电，没有较大的启动电流冲击，寿命比交流接触器长，适用于可靠性要求高或要求频繁动作的场合。","explanation":"对应课本关于交流接触器与直流接触器主触点、铁芯及发热对比的章节画线原文。"}]' WHERE id = 'electromechanical-transmission-memorize-supplement';